//! Venus bridge reporter. The reference image stays outside the repository;
//! only independently generated bytes are ever written to the output file.
use std::{env, fs};
use firmware_tools::devices::xiaomi_nabu::{venus_plan, venus_runtime_bridge as bridge};

fn run() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<_> = env::args().skip(1).collect();
    let (command, file) = match args.as_slice() {
        [command, file] => (command.as_str(), file.as_str()),
        _ => return Err("usage: venus_bridge <emit|emit-joined|verify|verify-joined> <filename>".into()),
    };
    let fragment = bridge::fragment()?;
    match command {
        "emit" => {
            fs::write(file, &fragment)?;
            println!("Emitted {} Venus bridge bytes [0x{:x},0x{:x}), partial firmware.",
                fragment.len(), bridge::START, bridge::END);
        }
        "emit-joined" => {
            let contiguous=bridge::contiguous_boot_and_bridge()?.build_complete()?;
            fs::write(file, &contiguous)?;
            println!("Emitted {} contiguous Venus boot+bridge bytes at file offset 0x{:x}; partial firmware.",
                     contiguous.len(), venus_plan::START_FILE_OFFSET);
        }
        "verify" | "verify-joined" => {
            let ref_image = fs::read(file)?;
            let (offset, generated) = if command == "verify" {
                (bridge::FILE_OFFSET, fragment)
            } else {
                (venus_plan::START_FILE_OFFSET, bridge::contiguous_boot_and_bridge()?.build_complete()?)
            };
            let end = offset.checked_add(generated.len()).ok_or("file region overflow")?;
            let expected = ref_image.get(offset..end).ok_or("reference firmware truncated")?;
            if generated != expected {
                let first = generated.iter().zip(expected.iter()).position(|(x, y)| x != y).unwrap();
                return Err(format!("mismatch at file offset 0x{:x} (runtime 0x{:x}): got {:02x}, expected {:02x}",
                    offset + first, offset + first - 0x4000, generated[first], expected[first]).into());
            }
            println!("Exact match: {} generated bytes at file offset 0x{:x}; not a complete firmware.", generated.len(), offset);
        }
        _ => return Err("unknown command; use emit, verify, or verify-joined".into()),
    }
    Ok(())
}
fn main() {
    if let Err(err) = run() {
        eprintln!("{err}");
        std::process::exit(1);
    }
}
